struct l2cap_le_conn_req { __le16 psm; __le16 scid; __le16 mtu; __le16 mps; __le16 credits; };
struct l2cap_chan { int imtu; int mps; int rx_credits; int scid; };

static __u16 __le16_to_cpu(__le16 x) { return x; }

struct l2cap_chan *l2cap_global_chan_by_psm(int a, __le16 b, void *c, void *d, int e);

static int l2cap_le_connect_req(struct l2cap_conn *conn,
				struct l2cap_cmd_hdr *cmd, __u16 cmd_len,
				u8 *data)
{
	struct l2cap_le_conn_req *req = (struct l2cap_le_conn_req *) data;
	struct l2cap_le_conn_rsp rsp;
	struct l2cap_chan *chan, *pchan;
	__u16 dcid, scid, credits, mtu, mps;
	__le16 psm;
	u8 result;

	scid = __le16_to_cpu(req->scid);
	mtu  = __le16_to_cpu(req->mtu);
	mps  = __le16_to_cpu(req->mps);
	psm  = req->psm;
	dcid = 0;
	credits = 0;

	if (!psm || __le16_to_cpu(psm) > 0x00ff) {
		result = 0x0002;
		chan = NULL;
		goto response;
	}

	pchan = l2cap_global_chan_by_psm(0, psm, &conn->x, &conn->x, 0);
	if (!pchan) {
		result = 0x0002;
		chan = NULL;
		goto response;
